import { NgTemplateOutlet } from '@angular/common';
import {
    afterNextRender,
    Component,
    computed,
    DestroyRef,
    effect,
    ElementRef,
    inject,
    signal,
    viewChild,
} from '@angular/core';
import { MatMenuModule } from '@angular/material/menu';
import { MatTooltipModule } from '@angular/material/tooltip';
import { NavigationEnd, Router, RouterModule } from '@angular/router';
import {
    i18n,
    OrganisationService,
    settingSignal,
    SettingsService,
    userSignal,
} from '@placeos/common';
import { IconComponent } from '@placeos/components';

export interface TopMenuEmbedItem {
    id: string;
    name: string;
    url: string;
    icon?: string;
    external?: boolean;
}

interface TopMenuRoute {
    id: string;
    route: string;
    url?: string;
    icon: string;
    name: string;
    embed?: boolean;
    external?: boolean;
}

interface TopMenuSettingsState {
    settings_initialised: boolean;
    org_initialised: boolean;
    has_region_context: boolean;
    has_building_context: boolean;
    override_count: number;
    required_override_count: number;
}

const TOP_MENU_FEATURE_ALIASES: Record<string, string[]> = {
    'parking-requests': ['parking', 'parking-requests'],
};

export function hasActiveTopMenuFeature(type: string, features: string[]) {
    const feature_names = TOP_MENU_FEATURE_ALIASES[type] || [type];
    return feature_names.some((_) => features.includes(_));
}

export function hasLoadedTopMenuSettings(state: TopMenuSettingsState) {
    return (
        !!state.settings_initialised &&
        !!state.org_initialised &&
        state.has_region_context &&
        state.has_building_context &&
        state.override_count >= state.required_override_count
    );
}

@Component({
    selector: 'top-menu',
    template: `
        @if (routes().length > 1) {
            <div
                #menuContainer
                menu
                [class.opacity-0]="mobile_menu() || checking()"
                [class.h-0!]="mobile_menu()"
                (window:resize)="checkMenu()"
                class="text-base-content flex h-full w-full min-w-full items-center justify-center overflow-hidden"
            >
                @for (route of visible_routes(); track trackRoute(route)) {
                    @if (route.external) {
                        <a
                            matRipple
                            [name]="'nav-' + route.id"
                            class="relative flex items-center justify-center space-x-2 px-8"
                            [href]="route.url"
                            target="_blank"
                            rel="noopener noreferrer"
                            [matTooltip]="route.name"
                            matTooltipPosition="below"
                        >
                            <ng-container
                                [ngTemplateOutlet]="route_contents"
                                [ngTemplateOutletContext]="{ route }"
                            />
                        </a>
                    } @else {
                        <a
                            matRipple
                            [name]="'nav-' + route.id"
                            class="relative flex items-center justify-center space-x-2 px-8"
                            [routerLink]="route.route"
                            routerLinkActive="text-secondary active"
                            [matTooltip]="route.name"
                            matTooltipPosition="below"
                        >
                            <ng-container
                                [ngTemplateOutlet]="route_contents"
                                [ngTemplateOutletContext]="{ route }"
                            />
                            <div
                                bar
                                class="bg-secondary absolute inset-x-0 bottom-0 h-0.5"
                            ></div>
                        </a>
                    }
                }
            </div>
        }
        @if (mobile_menu()) {
            <div
                class="absolute inset-y-0 -right-20 left-0 flex items-center justify-end"
            >
                <button icon default matRipple [matMenuTriggerFor]="menu">
                    <icon>menu</icon>
                </button>
            </div>
        }
        <mat-menu #menu="matMenu">
            @for (route of visible_routes(); track trackRoute(route)) {
                @if (route.external) {
                    <a
                        mat-menu-item
                        [href]="route.url"
                        target="_blank"
                        rel="noopener noreferrer"
                    >
                        <ng-container
                            [ngTemplateOutlet]="mobile_route_contents"
                            [ngTemplateOutletContext]="{ route }"
                        />
                    </a>
                } @else {
                    <a
                        mat-menu-item
                        [routerLink]="route.route"
                        routerLinkActive="bg-info-light! active"
                    >
                        <ng-container
                            [ngTemplateOutlet]="mobile_route_contents"
                            [ngTemplateOutletContext]="{ route }"
                        />
                    </a>
                }
            }
        </mat-menu>
        <ng-template #route_contents let-route="route">
            <icon filled class="text-xl" [class.mx-auto]="hide_text()">{{
                route.icon
            }}</icon>
            <icon
                outline
                className="material-symbols-outlined"
                [class.mx-auto]="hide_text()"
                class="m-0! text-xl"
            >
                {{ route.icon }}
            </icon>
            @if (!hide_text()) {
                <span class="truncate">{{ route.name }}</span>
            }
        </ng-template>
        <ng-template #mobile_route_contents let-route="route">
            <div class="flex items-center space-x-2">
                <icon filled class="text-xl">{{ route.icon }}</icon>
                <icon
                    outline
                    className="material-symbols-outlined"
                    class="text-xl"
                >
                    {{ route.icon }}
                </icon>
                <div class="truncate pr-4">{{ route.name }}</div>
            </div>
        </ng-template>
    `,
    styles: [
        `
            [menu] > * {
                height: 3.5rem;
                shrink: 1;
            }

            [bar] {
                display: none;
            }

            .active > [bar] {
                display: block;
            }

            a:not([mat-menu-item]):not(.active) {
                opacity: 0.6;
            }

            a:not([mat-menu-item]):not(.active):hover {
                border-radius: 0.5rem;
                margin-top: 0.25rem;
                margin-bottom: 0.25rem;
                height: 3rem;

                background-color: var(--base-200);
                opacity: 0.4;
            }

            a:not(.active) [filled],
            a.active [outline] {
                display: none;
            }
        `,
    ],
    imports: [
        MatMenuModule,
        IconComponent,
        RouterModule,
        MatTooltipModule,
        NgTemplateOutlet,
    ],
})
export class TopMenuComponent {
    private _element = inject(ElementRef);
    private _org = inject(OrganisationService);
    private _router = inject(Router);
    private _settings = inject(SettingsService);
    private _destroy_ref = inject(DestroyRef);

    private readonly menu =
        viewChild<ElementRef<HTMLDivElement>>('menuContainer');

    public readonly building = this._org.active_building;
    private readonly settings_initialised = signal(
        this._settings.is_initialised,
    );
    private readonly settings_ready = computed(() => {
        const region = this._org.active_region();
        const building = this._org.active_building();
        const overrides = this._settings.overrides();
        const has_region_context = !this._org.regions.length || !!region?.id;
        const required_overrides = (this._org.settings?.length || 0) + 2;
        return hasLoadedTopMenuSettings({
            settings_initialised: this.settings_initialised(),
            org_initialised: this._org.initialised(),
            has_region_context,
            has_building_context: !!building?.id,
            override_count: overrides.length,
            required_override_count: required_overrides,
        });
    });
    private readonly previous_size = signal(9999);
    public readonly checking = signal(false);
    public readonly mobile_menu = signal(false);
    public readonly hide_text = signal(false);

    public readonly setBuilding = (b) => (this._org.building = b);
    public readonly user = userSignal();
    public readonly feature_list = settingSignal<string[]>('features', []);
    public readonly feature_groups = settingSignal<Record<string, string[]>>(
        'feature_groups',
        {},
    );
    public readonly default_page = settingSignal(
        'app.default_route',
        '/landing',
    );
    public readonly new_features = settingSignal('app.new_features', false);
    public readonly menu_embeds = settingSignal<TopMenuEmbedItem[]>(
        'menu_embeds',
        [],
    );

    public readonly is_admin = computed(() => {
        const groups = this.user().groups;
        return (
            groups.includes('placeos_admin') ||
            groups.includes('placeos_support')
        );
    });

    public readonly features = computed(() => {
        const feature_list = this.feature_list();
        const feature_groups = this.feature_groups();
        const groups = this.user().groups;
        return feature_list.filter(
            (name) =>
                !feature_groups[name]?.length ||
                feature_groups[name].find((_) => groups.includes(_)),
        );
    });

    private readonly url = signal(this._router.url);

    public readonly type = computed(() => {
        const url = this.url();
        const default_page = this.default_page();
        if (url.includes(default_page)) return 'home';
        if (url.includes('book/spaces')) return 'spaces';
        if (url.includes('book/desk')) return 'desks';
        if (url.includes('book/locker')) return 'lockers';
        if (url.includes('book/parking-request')) return 'parking-requests';
        if (url.includes('book/parking')) return 'parking';
        if (url.includes('explore')) return 'explore';
        if (url.includes('schedule')) return 'schedule';
        return '';
    });

    public readonly routes = computed<TopMenuRoute[]>(() => [
        {
            id: 'home',
            route: this.default_page(),
            icon: 'home',
            name: i18n('APP.WORKPLACE.MENU_HOME'),
        },
        {
            id: 'spaces',
            route: '/book/meeting',
            icon: 'meeting_room',
            name: i18n('APP.WORKPLACE.MENU_ROOMS'),
        },
        {
            id: 'desks',
            route: '/book/desk',
            icon: 'desk',
            name: i18n('APP.WORKPLACE.MENU_DESKS'),
        },
        {
            id: 'lockers',
            route: '/book/locker',
            icon: 'lock',
            name: i18n('APP.WORKPLACE.MENU_LOCKERS'),
        },
        {
            id: 'parking',
            route: '/book/parking',
            icon: 'directions_car',
            name: i18n('APP.WORKPLACE.MENU_PARKING'),
        },
        {
            id: 'parking-requests',
            route: '/book/parking-request',
            icon: 'local_parking',
            name: i18n('APP.WORKPLACE.MENU_PARKING_REQUESTS'),
        },
        {
            id: 'visitor-invite',
            route: '/book/visitor',
            icon: 'person',
            name: i18n('APP.WORKPLACE.MENU_VISITORS'),
        },
        {
            id: 'explore',
            route: '/explore',
            icon: 'place',
            name: i18n('APP.WORKPLACE.MENU_EXPLORE'),
        },
        {
            id: 'schedule',
            route: '/your-bookings',
            icon: 'event',
            name: i18n('APP.WORKPLACE.MENU_SCHEDULE'),
        },
        {
            id: 'control',
            route: '/control',
            icon: 'remote_gen',
            name: i18n('APP.WORKPLACE.MENU_CONTROL'),
        },
        {
            id: 'group-events',
            route: '/group-events',
            icon: 'local_activity',
            name: i18n('APP.WORKPLACE.MENU_EVENTS'),
        },
        {
            id: 'deals-n-offers',
            route: '/deals-n-offers',
            icon: 'confirmation_number',
            name: i18n('APP.WORKPLACE.MENU_DEALS'),
        },
        ...this.menu_embeds()
            .filter((item) => item?.id && item?.name && item?.url)
            .map((item) => ({
                id: `embed-${item.id}`,
                route: item.external
                    ? item.url
                    : `/embedded/${encodeURIComponent(item.id)}`,
                url: item.external ? item.url : undefined,
                icon: item.icon || 'open_in_browser',
                name: item.name,
                embed: true,
                external: !!item.external,
            })),
    ]);

    public readonly visible_routes = computed(() => {
        const features = this.features();
        return this.routes().filter(
            (route) =>
                route.embed ||
                route.id === 'home' ||
                features.includes(route.id),
        );
    });

    public readonly trackRoute = (route: TopMenuRoute) => route.id;

    private _check_menu_timer: ReturnType<typeof setTimeout> | null = null;

    constructor() {
        this.checking.set(true);
        const settings_sub = this._settings.initialised.subscribe((value) =>
            this.settings_initialised.set(value),
        );
        const route_sub = this._router.events.subscribe((event) => {
            if (event instanceof NavigationEnd) this.url.set(this._router.url);
        });
        this._destroy_ref.onDestroy(() => {
            settings_sub.unsubscribe();
            route_sub.unsubscribe();
        });

        effect(() => {
            this.building();
            this.visible_routes();
            this._checkRoute();
        });

        afterNextRender(() => {
            this._scheduleCheckMenu(300);
        });
    }

    private _checkRoute() {
        if (!this.settings_ready()) {
            this._scheduleCheckMenu(300);
            return;
        }
        const type = this.type();
        const features = this.features();
        if (
            type &&
            type !== 'home' &&
            !hasActiveTopMenuFeature(type, features)
        ) {
            this._router.navigate(['/']);
        }
        this._scheduleCheckMenu(300);
    }

    private _scheduleCheckMenu(delay: number) {
        if (this._check_menu_timer) {
            clearTimeout(this._check_menu_timer);
        }
        this._check_menu_timer = setTimeout(() => this.checkMenu(), delay);
    }

    public checkMenu() {
        const menu_el = this.menu();
        const menu_width = menu_el?.nativeElement?.offsetWidth || 0;
        const container_width =
            this._element.nativeElement.parentElement?.offsetWidth || 0;
        this.checking.set(false);
        if (menu_width > container_width && !this.hide_text()) {
            this.hide_text.set(true);
            this._scheduleCheckMenu(20);
            this.checking.set(true);
            this.previous_size.set(container_width);
            return;
        }
        if (this.hide_text()) {
            this.mobile_menu.set(menu_width > container_width);
        }
        if (container_width > this.previous_size() && this.hide_text()) {
            this.hide_text.set(false);
            this._scheduleCheckMenu(20);
            this.checking.set(true);
        }
        this.previous_size.set(container_width);
    }
}
